"""Build an offline human/equipment viewer from renderer exports, preserving image bytes."""
from pathlib import Path
import base64,json,html,zipfile
root=Path(__file__).resolve().parents[1];kit=root/'dist/humans-kit'
manifest=json.loads((kit/'manifest.json').read_text());sprites={k:'data:image/png;base64,'+base64.b64encode((kit/v).read_bytes()).decode() for k,v in manifest.items()}
page='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bloodmoon · Classes humanas</title><style>
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% 0,#401e2d44,transparent 60%),#120e15;color:#e5d7dc;font-family:Arial,sans-serif}header,main,footer{max-width:1280px;margin:auto;padding:25px 35px}header{display:flex;justify-content:space-between;border-bottom:1px solid #60334966;align-items:center}.brand{font:700 21px Georgia;letter-spacing:4px}.brand b{color:#c55778;font-size:30px}header>span{font-size:8px;letter-spacing:2px;color:#b78b9e}h1{font:40px/1.18 Georgia;margin:15px 0}h1 em{color:#c9879f;font-weight:400}.eyebrow{font-size:8px;letter-spacing:2px;color:#b67c92}.heading{display:flex;align-items:end;justify-content:space-between;margin:5px 0 30px}.heading p{font-size:11px;line-height:1.9;color:#a68c9b}.controls{display:flex;gap:12px;flex-wrap:wrap;padding:18px;background:#211622;border:1px solid #5b324866;margin-bottom:18px}label{font-size:9px;color:#bd98ab;display:flex;flex-direction:column;gap:8px;flex:1;min-width:125px}select,button{font:inherit;color:inherit;background:#251824;border:1px solid #78425877;padding:12px;cursor:pointer}select{font-size:11px}button:hover{border-color:#d37a9b}button:focus-visible,select:focus-visible{outline:2px solid #e394af;outline-offset:3px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.character{padding:20px 12px 23px;border:1px solid #68425566;background:radial-gradient(ellipse at 50% 60%,#54334b44,transparent 65%),#1b131e;text-align:center;cursor:pointer}.character.selected{border-color:#c26a8c}.character>small{display:block;color:#c18ba3;letter-spacing:2px;font-size:8px}.character canvas{display:block;width:100%;height:auto;max-width:360px;margin:auto}.character h2{font:27px Georgia;margin:0 0 8px}.character p{font-size:10px;color:#a58d9c;margin:0}.character>span{font-size:8px;color:#bfa5ae;display:block;margin-top:13px;letter-spacing:1px}.toolbar{display:flex;gap:8px;align-items:center;margin:15px 0 25px}.toolbar button{font-size:9px;padding:12px 18px}.toolbar span{font:10px monospace;color:#bd91a6;margin-left:8px}.download{margin-left:auto;background:#6f2f4d!important;border-color:#ad5579!important}.label{font-size:9px;letter-spacing:1.7px;color:#b4829a;margin:27px 0 13px}.stages{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stage{background:#201522;border:1px solid #69415755;text-align:center;padding:10px 7px 18px}.stage canvas{width:100%;height:auto;max-width:220px}.stage h3{font:18px Georgia;margin:0}.stage p{font-size:9px;color:#a48799}.note{font-size:10px;color:#a38d9b;line-height:1.9;margin-top:24px}.note a,footer a{color:#cb9fb6}footer{display:flex;justify-content:space-between;font-size:8px;color:#876979;padding-bottom:30px}details{max-width:1210px;margin:20px auto;padding:20px;border-top:1px solid #69415755;color:#bca1af;font-size:11px}pre{white-space:pre-wrap;font:10px/1.6 monospace}#status{font-size:10px;color:#b68d9f;margin-bottom:15px}@media(max-width:720px){header,main,footer{padding-left:15px;padding-right:15px}.heading{display:block}h1{font-size:30px}.heading p{font-size:10px}.cards{gap:6px}.character{padding:15px 3px}.character h2{font-size:18px}.character p{font-size:8px;line-height:1.6}.character>small{font-size:6px;letter-spacing:1px}.character>span{font-size:6px}.controls{gap:8px;padding:12px}.controls label{min-width:42%}.toolbar{flex-wrap:wrap}.toolbar .download{margin-left:0}.toolbar span{font-size:8px}.stages{grid-template-columns:repeat(2,1fr)}header>span{font-size:6px;max-width:100px;text-align:right}.brand{font-size:16px}}
</style></head><body><header><div class="brand"><b>◕</b> BLOODMOON</div><span>TRÊS CLASSES · SEMPRE HUMANOS NO INÍCIO</span></header><main><div class="heading"><div><span class="eyebrow">A JORNADA COMEÇA COM ROUPAS SIMPLES</span><h1>O humano é a base.<br><em>O equipamento vem depois.</em></h1></div><p>Mesmo corpo, novas conquistas.<br>Vista as três classes e compare as oito direções.</p></div><div id="status">Carregando sprites locais…</div><div class="controls"><label>ARMADURA<select id="armor"><option value="none">Roupa inicial · sem armadura</option><option value="couro">Armadura de couro</option><option value="cota">Cota de malha</option><option value="placas">Armadura de placas</option></select></label><label>ARMA<select id="weapon"><option value="none">Mãos livres</option><option value="class">Arma de classe</option><option value="espada">Espada de ferro</option></select></label><label>DIREÇÃO<select id="direction"><option>↓ S</option><option>↙ SW</option><option>← W</option><option>↖ NW</option><option>↑ N</option><option>↗ NE</option><option>→ E</option><option>↘ SE</option></select></label><label>MOVIMENTO<select id="motion"><option value="idle">Parado</option><option value="walk">Andar</option><option value="run">Correr</option></select></label></div><section id="cards" class="cards"></section><div class="toolbar"><button id="previous">← QUADRO</button><button id="play">REPRODUZIR</button><button id="next">QUADRO →</button><span id="frameLabel"></span><button id="download" class="download">BAIXAR SPRITESHEET PNG ↗</button></div><div class="label" id="progressionTitle">EVOLUÇÃO VISUAL</div><section id="stages" class="stages"></section><p class="note">Prévia offline: não depende de servidor e não altera personagens. Clique em uma classe para inspecioná-la e baixar sua spritesheet. Todas as peças compartilham o rig, a direção e o quadro do corpo. Humanos usam o ciclo Flare com cadências diferentes para andar e correr. As transformações são um conjunto separado.<br>Arte humana Flare e composições sob <a href="#credits">CC BY-SA 3.0 · créditos completos</a>.</p></main><footer><span>BLOODMOON · HUMANOS EM CAMADAS</span><span>8 DIREÇÕES · 8 QUADROS · CÉLULAS 160×160</span></footer>__CREDITS__<script>
const SOURCES=__SPRITES__;
const $=id=>document.getElementById(id),kinds=['cacador','vampiro','lobisomem'],names={cacador:'Caçador',vampiro:'Vampiro',lobisomem:'Lobisomem'},roles={cacador:'Sentinela · humano equilibrado',vampiro:'Adepto · humano esguio',lobisomem:'Errante · humano robusto'},images={},cards=[],stages=[];let selected='cacador',frame=0,playing=false,ready=false,last=0,elapsed=0;
function paint(canvas,kind,armor,weapon,scale=2.3){if(!ready)return;const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height,baseKey=kind+'-'+armor+'-'+weapon,im=($('motion').value==='idle'?images[baseKey+'-idle']:null)||images[baseKey],d=$('direction').selectedIndex;c.clearRect(0,0,w,h);c.fillStyle='#0004';c.beginPath();c.ellipse(w/2,h*.87,50*scale/2.3,8*scale/2.3,0,0,Math.PI*2);c.fill();c.imageSmoothingEnabled=true;c.drawImage(im,frame*160,d*160,160,160,w/2-80*scale,h*.87-128*scale,160*scale,160*scale);}
for(const kind of kinds){const card=document.createElement('div'),canvas=document.createElement('canvas');canvas.width=360;canvas.height=360;card.className='character';card.setAttribute('role','button');card.tabIndex=0;const small=document.createElement('small'),h=document.createElement('h2'),p=document.createElement('p'),label=document.createElement('span');small.textContent='CLASSE HUMANA';h.textContent=names[kind];p.textContent=roles[kind];card.append(small,canvas,h,p,label);card.onclick=()=>{selected=kind;draw();};card.onkeydown=e=>{if(e.code==='Enter'||e.code==='Space'){e.preventDefault();selected=kind;draw();}};$('cards').append(card);cards.push({kind,card,canvas,label});}
for(const [armor,title] of [['none','Roupa simples'],['couro','Couro'],['cota','Malha'],['placas','Placas']]){const card=document.createElement('div'),canvas=document.createElement('canvas'),h=document.createElement('h3'),p=document.createElement('p');canvas.width=240;canvas.height=270;card.className='stage';h.textContent=title;p.textContent=armor==='none'?'Início da jornada':'Equipamento conquistado';card.append(canvas,h,p);$('stages').append(card);stages.push({armor,canvas});}
function draw(){if(!ready)return;for(const v of cards){paint(v.canvas,v.kind,$('armor').value,$('weapon').value);v.card.classList.toggle('selected',selected===v.kind);v.card.setAttribute('aria-pressed',selected===v.kind);v.label.textContent=$('armor').value==='none'&&$('weapon').value==='none'?'ROUPA INICIAL':'EQUIPAMENTO EM CAMADAS';}for(const s of stages)paint(s.canvas,selected,s.armor,s.armor==='none'?'none':'espada',1.65);$('progressionTitle').textContent='EVOLUÇÃO VISUAL · '+names[selected].toUpperCase();$('frameLabel').textContent='QUADRO '+(frame+1)+' / 8';$('play').textContent=playing?'PAUSAR':'REPRODUZIR';}
for(const key of ['armor','weapon','direction','motion'])$(key).onchange=()=>{frame=0;elapsed=0;if(key==='motion')playing=$('motion').value!=='idle';draw();};$('play').onclick=()=>{playing=!playing;if(playing&&$('motion').value==='idle')$('motion').value='walk';draw();};function step(n){playing=false;frame=(frame+n+8)%8;draw();}$('previous').onclick=()=>step(-1);$('next').onclick=()=>step(1);$('download').onclick=()=>{const a=document.createElement('a'),key=selected+'-'+$('armor').value+'-'+$('weapon').value;a.download='bloodmoon-humano-'+key+'.png';a.href=($('motion').value==='idle'?SOURCES[key+'-idle']:null)||SOURCES[key];a.click();};
Promise.all(Object.entries(SOURCES).map(([key,src])=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[key]=im;resolve();};im.onerror=reject;im.src=src;}))).then(()=>{ready=true;$('status').textContent='PRONTO · COMECE COM ROUPA SIMPLES E EXPERIMENTE OS EQUIPAMENTOS';draw();}).catch(()=>{$('status').textContent='Não foi possível carregar a prévia.';});
function tick(t){const dt=last?Math.min(t-last,100):0;last=t;if(playing&&ready){elapsed+=dt;const ms=$('motion').value==='run'?65:110;if(elapsed>=ms){elapsed%=ms;frame=(frame+1)%8;draw();}}requestAnimationFrame(tick);}requestAnimationFrame(tick);
</script></body></html>'''
credits='<details id="credits"><summary>Créditos e licenças da arte humana</summary>'
for name in ['ATTRIBUTION.md','CREDITS.txt','LICENSE.txt']:credits+='<h3>'+html.escape(name)+'</h3><pre>'+html.escape((root/'assets/flare'/name).read_text())+'</pre>'
credits+='</details>'
page=page.replace('__SPRITES__',json.dumps(sprites,separators=(',',':'))).replace('__CREDITS__',credits)
out=root/'dist/Bloodmoon-Humanos.html';out.write_text(page)
readme='''BLOODMOON — HUMANOS E EQUIPAMENTOS\n\nAbra Bloodmoon-Humanos.html no navegador, sem servidor e sem Internet.\nTrês classes humanas começam em roupas simples, sem arma ou armadura. Use os controles para experimentar couro, cota de malha, placas e espada ou arma de classe.\n\nAs 36 combinações de equipamentos e as 3 bases em postura de descanso contêm as combinações das três bases x quatro roupas/armaduras x três opções de arma. Cada PNG mede 1280x1280, com oito colunas de quadros e oito linhas de direções S/SW/W/NW/N/NE/E/SE. Célula 160x160, pivô dos pés (80,128).\n\nArquivos *-none-none.png são as bases iniciais, sem equipamento. Os outros são composições em camadas exportadas pelo renderer do jogo. No jogo, arma e armadura continuam em camadas independentes; estes PNGs servem para revisão e integração externa. Humanos compartilham o ciclo Flare, com cadência diferente para andar/correr.\n\nArte humana e composições: Flare e seus contribuidores, CC BY-SA 3.0. Créditos e licença completos incluídos no HTML e nos arquivos de texto.\n'''
(kit/'LEIA-ME.txt').write_text(readme)
for name in ['ATTRIBUTION.md','CREDITS.txt','LICENSE.txt']:(kit/('Flare-'+name)).write_bytes((root/'assets/flare'/name).read_bytes())
zipfile_path=root/'dist/Bloodmoon-Humanos.zip'
with zipfile.ZipFile(zipfile_path,'w',zipfile.ZIP_DEFLATED) as z:
 z.write(out,out.name)
 for f in kit.iterdir():
  if f.is_file():z.write(f,f.name)
print('HTML offline:',round(out.stat().st_size/1048576,2),'MiB; ZIP:',round(zipfile_path.stat().st_size/1048576,2),'MiB')
